package rootio

// GPGPublicKeyBase64 is the base64-encoded dearmored GPG public key for the Root.io APT repository.
// Keep in sync with backend/internal/constants/debian.go DebianGPGPublicKeyBase64.
const GPGPublicKeyBase64 = ""

// APKPublicKeyBase64 is the base64-encoded RSA public key for the Root.io APK repository.
// APK uses RSA signatures (not GPG), so this is a separate key from GPGPublicKeyBase64.
// Keep in sync with backend/internal/constants/alpine.go AlpinePublicKeyBase64.
const APKPublicKeyBase64 = ""
